namespace {
void check(bool b,const char* m){if(!b)throw std::runtime_error(m);}
void ready(hem::ReadAheadTransport& t,int n){auto deadline=juce::Time::getMillisecondCounter()+5000;while(!t.availableRt(n)&&juce::Time::getMillisecondCounter()<deadline)juce::Thread::sleep(1);check(t.availableRt(n),"ready timeout");}
juce::File fixture(const juce::File& dir,int rate,int frames){auto f=dir.getChildFile(juce::String(rate)+"-"+juce::String(frames)+".wav");auto stream=f.createOutputStream();juce::WavAudioFormat wav;std::unique_ptr<juce::AudioFormatWriter> w(wav.createWriterFor(stream.get(),rate,2,32,{},0));check(bool(w),"fixture writer");stream.release();juce::AudioBuffer<float> a(2,frames);for(int i=0;i<frames;++i){a.setSample(0,i,float(.21*std::sin(2*juce::MathConstants<double>::pi*997*i/rate)+.07*std::cos(2*juce::MathConstants<double>::pi*173*i/rate)));a.setSample(1,i,float(.13*std::cos(2*juce::MathConstants<double>::pi*683*i/rate)-.02));}check(w->writeFromAudioSampleBuffer(a,0,frames),"fixture write");return f;}
// Independent reader/resampler graph: follows the agreed legacy target-floor,
// source-floor and flush law. It intentionally does NOT compare fractional seeks
// with slices of continuous playback, which promise a different initial phase.
juce::AudioBuffer<float> oracle(const juce::File& file,double target,juce::int64 targetStart,int count){juce::AudioFormatManager formats;formats.registerBasicFormats();auto* raw=formats.createReaderFor(file);check(raw!=nullptr,"oracle reader");const double sourceRate=raw->sampleRate;juce::AudioFormatReaderSource source(raw,true);source.setNextReadPosition(juce::int64(std::floor(static_cast<long double>(targetStart)*sourceRate/target)));juce::ResamplingAudioSource resampler(&source,false,2);resampler.setResamplingRatio(sourceRate/target);resampler.prepareToPlay(2048,target);juce::AudioBuffer<float> out(2,count);for(int offset=0;offset<count;offset+=2048)resampler.getNextAudioBlock({&out,offset,std::min(2048,count-offset)});return out;}
void compare(hem::ReadAheadTransport& t,const juce::AudioBuffer<float>& expected,double rate,juce::int64 start,double duration){const int pattern[]{1,63,128,255,256,513,2048};juce::AudioBuffer<float> block(2,2060);int consumed=0,index=0;t.start();while(consumed<expected.getNumSamples()){const int n=pattern[index++%7];ready(t,n);block.clear();block.setSample(0,0,.8125f);block.setSample(1,2059,-.8125f);check(t.renderRt({&block,3,n}),"unexpected render failure");check(block.getSample(0,0)==.8125f&&block.getSample(1,2059)==-.8125f,"render changed outside region");const int actual=std::min(n,expected.getNumSamples()-consumed);for(int c=0;c<2;++c)for(int i=0;i<n;++i){const float want=i<actual?expected.getSample(c,consumed+i):0;check(std::abs(block.getSample(c,3+i)-want)<2e-6f,"PCM mismatch or EOF padding error");}consumed+=actual;check(std::abs(t.getCurrentPosition()-std::min(duration,double(start+consumed)/rate))<1e-10,"emitted frame cursor mismatch");}check(!t.isPlaying()&&!t.hasUnderrun()&&!t.hasReadError(),"EOF incorrectly playing/faulted");block.clear();check(t.renderRt({&block,0,32})&&block.getMagnitude(0,32)==0,"post EOF not silent");}
}
int main(){juce::ScopedJuceInitialiser_GUI gui;juce::TimeSliceThread disk("alignment reader");disk.startThread();const auto dir=juce::File::getCurrentWorkingDirectory().getChildFile("pitch-time-work").getChildFile("transport-alignment-"+juce::Uuid().toString());try{check(dir.createDirectory().wasOk(),"fixture directory");juce::AudioFormatManager formats;formats.registerBasicFormats();int cases=0;
for(int sourceRate:{44100,48000,96000})for(int frames:{1,17,257,48007}){auto file=fixture(dir,sourceRate,frames);const auto hash=juce::SHA256(file).toHexString();for(int targetRate:{44100,48000,96000}){hem::ReadAheadTransport t;t.prepareFile(file,formats,disk,targetRate,2048);check(!t.isPlaying(),"prepare started playback");check(t.getSourceSampleRate()==sourceRate&&t.getSourceChannels()==2,"source metadata changed");const double duration=double(frames)/sourceRate;check(std::abs(t.getLengthInSeconds()-duration)<1e-12,"source duration changed");const auto total=juce::int64(std::ceil(static_cast<long double>(frames)*targetRate/sourceRate));auto expected=oracle(file,targetRate,0,int(total));compare(t,expected,targetRate,0,duration);++cases;
// Prepared 2026-10-16, unrun: exact/beyond EOF must not replay a fractional final frame.
for(double endPosition:{duration,duration+0.25/targetRate}){uint64_t endToken=0;check(t.prepareEpoch(endPosition,false,endToken).wasOk(),"EOF epoch prepare");check(t.commitPreparedEpoch(endToken,true),"EOF epoch commit");juce::AudioBuffer<float> endBlock(2,32);endBlock.clear();check(t.renderRt({&endBlock,0,32}),"EOF epoch render");check(endBlock.getMagnitude(0,32)==0&&!t.isPlaying(),"EOF seek replayed final frame");++cases;}
if(frames==48007){const double requested=.073219;const auto start=juce::int64(std::floor(requested*targetRate));uint64_t token=0;check(t.prepareEpoch(requested,false,token).wasOk(),"seek preparation");check(t.commitPreparedEpoch(token,false),"seek commit");check(std::abs(t.getCurrentPosition()-double(start)/targetRate)<1e-12,"seek target-floor cursor");auto seekExpected=oracle(file,targetRate,start,int(total-start));compare(t,seekExpected,targetRate,start,duration);++cases;}}
check(juce::SHA256(file).toHexString()==hash,"original file changed");check(file.deleteFile(),"fixture cleanup");}
// Thirteen independently prepared decoders must emit identical samples and
// positions despite different page refill timing and shared worker service.
auto file=fixture(dir,44100,96007);const auto hash=juce::SHA256(file).toHexString();{std::array<std::unique_ptr<hem::ReadAheadTransport>,13> group;std::array<juce::AudioBuffer<float>,13> buffers;for(int i=0;i<13;++i){group[i]=std::make_unique<hem::ReadAheadTransport>();group[i]->prepareFile(file,formats,disk,96000,513);buffers[i].setSize(2,513);group[i]->start();}for(int pass=0;pass<100;++pass){const int n=pass%2?513:255;for(auto& t:group)ready(*t,n);for(int i=0;i<13;++i)check(group[i]->renderRt({&buffers[i],0,n}),"group render fault");for(int i=1;i<13;++i){check(group[i]->getCurrentPosition()==group[0]->getCurrentPosition(),"group position drift");for(int c=0;c<2;++c)for(int j=0;j<n;++j)check(buffers[i].getSample(c,j)==buffers[0].getSample(c,j),"group PCM drift");}}
const double requested=.131234;std::array<uint64_t,13> tokens{};for(int i=0;i<13;++i)check(group[i]->prepareEpoch(requested,false,tokens[i]).wasOk(),"group seek prepare");for(int i=0;i<13;++i)check(group[i]->commitPreparedEpoch(tokens[i],true),"group seek commit");for(int i=0;i<13;++i){ready(*group[i],513);check(group[i]->renderRt({&buffers[i],0,513}),"group seek render");}for(int i=1;i<13;++i){check(group[i]->getCurrentPosition()==group[0]->getCurrentPosition(),"group seek cursor drift");for(int c=0;c<2;++c)for(int j=0;j<513;++j)check(buffers[i].getSample(c,j)==buffers[0].getSample(c,j),"group seek PCM drift");}}
check(juce::SHA256(file).toHexString()==hash,"group original modified");check(file.deleteFile()&&dir.deleteFile(),"group cleanup");disk.stopThread(5000);std::cout<<"PASS "<<cases<<" real-WAV rate/length/seek cases; ceil EOF, exact emitted cursor, region safety, 13-source alignment, original hashes. Legacy floor/flush seek only; continuous fractional-phase slice equivalence NOT promised.\n";return 0;}catch(const std::exception& e){std::cerr<<"FAIL "<<e.what()<<"; fixtures "<<dir.getFullPathName()<<"\n";disk.stopThread(5000);return 1;}}
